const issues=[];
function solidO(){return {type:'SOLID',color:{r:1,g:1,b:1},opacity:0};}
function nav(node,destId){
  try{node.reactions=[{action:{type:'NODE',destinationId:destId,navigation:'NAVIGATE',transition:{type:'SMART_ANIMATE',duration:300,easing:{type:'EASE_OUT'}}},trigger:{type:'CLICK'}}];}
  catch(e){try{node.reactions=[{action:{type:'NODE',destinationId:destId,navigation:'NAVIGATE'},trigger:{type:'CLICK'}}];}catch(e2){issues.push('react:'+e2.message);}}
}
function hotspot(parent,target,destId,name){
  const fb=parent.absoluteBoundingBox;
  let bb;
  if(target.absoluteBoundingBox){bb=target.absoluteBoundingBox;}else{issues.push('no bbox '+name);return null;}
  const h=figma.createRectangle();h.name=name;h.fills=[solidO()];
  h.resize(Math.max(24,bb.width),Math.max(24,bb.height));
  parent.appendChild(h);
  h.x=bb.x-fb.x;h.y=bb.y-fb.y;
  nav(h,destId);
  return h.id;
}
