for (const s of ['Regular','Medium','SemiBold','Bold']) await figma.loadFontAsync({family:'DM Sans',style:s});
const C={ink3:'#9C9CA6',good:'#12A66B',warn:'#DD8500',bad:'#E5484D'};
function hex(h){const n=parseInt(h.slice(1),16);return{r:(n>>16&255)/255,g:(n>>8&255)/255,b:(n&255)/255};}
function solid(h,o){return{type:'SOLID',color:hex(h),opacity:o===undefined?1:o};}
function findNode(root,name){const a=root.findAll(function(n){return n.name===name;});return a.length?a[0]:null;}
function setRow(ri,nameT,amountT,leftT,frac,colorHex,leftHex){
  const issues=[];const nameN=findNode(ri,'Name');const amN=findNode(ri,'Amount');const lfN=findNode(ri,'Left');const tk=findNode(ri,'Track');const fl=findNode(ri,'Fill');
  if(!nameN)issues.push('no Name');else nameN.characters=nameT;
  if(!amN)issues.push('no Amount');else amN.characters=amountT;
  if(!lfN)issues.push('no Left');else{lfN.characters=leftT;lfN.fills=[solid(leftHex||C.ink3)];}
  if(!tk)issues.push('no Track');if(!fl)issues.push('no Fill');
  if(tk&&fl){fl.fills=[solid(colorHex)];fl.resize(Math.max(6,Math.round(frac*(tk.width>10?tk.width:251))),5);}
  return issues;
}
const issues=[];
// Progress Row Top: stretch to 311 so Amount right-aligns
const pr=await figma.getNodeByIdAsync('10:11');
const topF=findNode(pr,'Top');
if(topF){topF.counterAxisSizingMode='FIXED';topF.resize(311,topF.height);}else issues.push('no Top');
// Budget BottomRow: fixed 311 so $2,550 right-aligns
const bc=await figma.getNodeByIdAsync('10:52');
const br=findNode(bc,'BottomRow');
if(br){br.primaryAxisSizingMode='FIXED';br.resize(311,br.height);}else issues.push('no BottomRow');
// Category Card Head: stretch to 311 so Total right-aligns
const cc=await figma.getNodeByIdAsync('10:19');
const head=findNode(cc,'Head');
if(head){head.counterAxisSizingMode='FIXED';head.resize(311,head.height);}else issues.push('no Head');
// re-apply fills with (hopefully fresh) track width
const auto=await figma.getNodeByIdAsync('12:98');
const bill=await figma.getNodeByIdAsync('12:124');
const a1=auto.children.find(function(c){return c.name==='Row 1';});
const a2=auto.children.find(function(c){return c.name==='Row 2';});
if(a1)issues.push.apply(issues,setRow(a1,'Auto & transport','$350','Left $186',0.653,C.good));
if(a2)issues.push.apply(issues,setRow(a2,'Auto insurance','$250','Left $120',0.676,C.good));
const b1=bill.children.find(function(c){return c.name==='Row 1';});
const b2=bill.children.find(function(c){return c.name==='Row 2';});
const b3=bill.children.find(function(c){return c.name==='Row 3';});
if(b1)issues.push.apply(issues,setRow(b1,'Subscriptions','$52','Left $0',1,C.warn,C.bad));
if(b2)issues.push.apply(issues,setRow(b2,'House service','$138','Left $10',0.93,C.warn));
if(b3)issues.push.apply(issues,setRow(b3,'Maintenance','$130','Left $30',0.8125,C.warn));
return {topW:topF.width,botRowW:br.width,headW:head.width,trkInRow:findNode(pr,'Track').width,issues:issues};

