function findNode(root,name){const a=root.findAll(function(n){return n.name===name;});return a.length?a[0]:null;}
const issues=[];
// 1) component: Track -> horizontal auto-layout with Fill(grow) + Spacer(grow)
const pr=await figma.getNodeByIdAsync('10:11');
const trk=findNode(pr,'Track');
trk.layoutMode='HORIZONTAL';
trk.primaryAxisSizingMode='FIXED';
trk.counterAxisSizingMode='FIXED';
trk.itemSpacing=0;
trk.counterAxisAlignItems='CENTER';
trk.clipsContent=false;
const fl=findNode(pr,'Fill');
fl.layoutGrow=0.653;
fl.resize(10,5);
const sp=figma.createRectangle();sp.name='Spacer';sp.fills=[];sp.resize(10,5);sp.layoutGrow=0.347;
trk.appendChild(sp);
// also fix component shells
function fixShell(ri){const top=findNode(ri,'Top');const bot=findNode(ri,'Bottom');if(top){top.counterAxisSizingMode='FIXED';top.resize(311,top.height);}if(bot){bot.counterAxisSizingMode='FIXED';bot.resize(311,bot.height);}}
fixShell(pr);
// 2) instances
const auto=await figma.getNodeByIdAsync('12:98');
const bill=await figma.getNodeByIdAsync('12:124');
function setRow2(ri,frac,colorHex,leftHex){
  fixShell(ri);
  const f=findNode(ri,'Fill');const lf=findNode(ri,'Left');
  const out=[];
  if(!f)out.push('no Fill');else{f.layoutGrow=frac;f.fills=[solid(colorHex)];f.resize(Math.max(6,f.width),5);}
  if(!lf)out.push('no Left');else lf.fills=[solid(leftHex||C.ink3)];
  return out;
}
const a1=auto.children.find(function(c){return c.name==='Row 1';});
const a2=auto.children.find(function(c){return c.name==='Row 2';});
if(a1)issues.push.apply(issues,setRow2(a1,0.653,C.good));
if(a2)issues.push.apply(issues,setRow2(a2,0.676,C.good));
const b1=bill.children.find(function(c){return c.name==='Row 1';});
const b2=bill.children.find(function(c){return c.name==='Row 2';});
const b3=bill.children.find(function(c){return c.name==='Row 3';});
if(b1)issues.push.apply(issues,setRow2(b1,1,C.warn,C.bad));
if(b2)issues.push.apply(issues,setRow2(b2,0.93,C.warn));
if(b3)issues.push.apply(issues,setRow2(b3,0.8125,C.warn));
const botW=findNode(a1,'Bottom').width;
const trkW=findNode(a1,'Track').width;
const flW=findNode(a1,'Fill').width;
return {a1BotW:botW,a1TrkW:trkW,a1FillW:flW,issues:issues};

